/// <summary>
/// PaffH 07.07.25
/// </summary>
/// <param name = "_inputContract">NDXTransferAX2009PALabelOZItemMappingInputContract</param>
/// <returns>NDXTransferAX2009PALabelOZItemMappingReturnContract</returns>
public NDXTransferAX2009PALabelOZItemMappingReturnContract OZItemMappingTransfer(NDXTransferAX2009PALabelOZItemMappingInputContract _inputContract)
{
    System.Exception ex;
    NDXTransferAX2009PALabelOZItemMappingReturnContract returnContract = NDXTransferAX2009PALabelOZItemMappingReturnContract::construct();
    returnContract.start();
    NDXTransferAX2009PALabelOZItemMappingContract itemContract;
    NDXUpdatedUTC nDXUpdatedUTC = DateTimeUtil::utcNow();
    container conCompany = conNull();
    conCompany += NDXHelperDataArea::DataAreaIdFromEnum(NDXDataAreaIdEnum::Niedax);
    conCompany += NDXHelperDataArea::DataAreaIdFromEnum(NDXDataAreaIdEnum::Kleinhuis);
    conCompany += NDXHelperDataArea::DataAreaIdFromEnum(NDXDataAreaIdEnum::Fintech);

    try
    {
        if (_inputContract.parmPictureItemList())
        {
            ListEnumerator enum = _inputContract.parmPictureItemList().getEnumerator();
            while (enum.moveNext())
            {
                itemContract = enum.current();
                returnContract.incrementElementsCounter();

                DataAreaId dataAreaId = itemContract.parmDataAreaId();
                if (conFind(conCompany, dataAreaId))
                {
                    changecompany(dataAreaId)
                    {
                        ItemId itemIdBase = itemContract.parmItemIdBase();
                        InventTable inventTable = InventTable::find(ItemIdBase);
                        if (!inventTable)
                        {
                            returnContract.addErrorToList(NDXErrorContract::construct('ItemNotFound', strFmt('Artikel (base) [%1-%2] nicht lokalisiert!', dataAreaId, ItemIdBase)));
                            continue;
                        }
                        NDXProdIdentOZMapping nDXProdIdentOZMapping = NDXProdIdentOZMapping::find(inventTable.ItemId, true);
                        if (nDXProdIdentOZMapping)
                        {
                            ItemId itemIdMapped = itemContract.parmItemIdMapped();
                            inventTable = InventTable::find(itemIdMapped);
                            if (!inventTable)
                            {
                                returnContract.addErrorToList(NDXErrorContract::construct('ItemNotFound', strFmt('Artikel (mapped) [%1-%2] nicht lokalisiert!', dataAreaId, ItemIdMapped)));
                                continue;
                            }

                            nDXProdIdentOZMapping.Active = itemContract.parmAktiv();
                            nDXProdIdentOZMapping.ItemIdMapped = itemIdMapped;
                            nDXProdIdentOZMapping.UpdatedUTC = nDXUpdatedUTC;
                            ttsbegin;
                            nDXProdIdentOZMapping.update();
                            ttscommit;
                            returnContract.incrementElementsCounter();
                        }
                    }
                }
            }
        }
    }
    catch (ex)
    {
        throw;
    }
    returnContract.end();
    return returnContract;
}
